exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', 'left join dmloaibv b on a.tag = b.ma_loai', 'b.ten_loai tag_name', '@@key', '', @@filterKey, '', @pageIndex, 50, @@admin, @@userId
declare @strKey nvarchar(3000) set @strKey = @strFinding exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', 'left join dmloaibv b on a.tag = b.ma_loai', 'b.ten_loai tag_name', '@@key', @strKey, @@filterKey, '', @pageIndex, 50, @@admin, @@userId

js.text:

function grid$dmvt(f){
  this.constructor(f);
}
grid$dmvt.prototype = new DirEvent();
grid$dmvt.prototype.afterInit = function(){
  var p = this._dir;
}

css.text:

td.noi_dung {
	display: -webkit-box;
	-webkit-line-clamp: 1;       /* Hiển thị tối đa 3 dòng */
	-webkit-box-orient: vertical;
	overflow: hidden;
	max-height: 4.5em;           /* Tùy theo font-size */
}
td.noi_dung img, td.noi_dung figure {
	display: none;
}
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
